// Exact official donor bytes, generated from the held J fixtures; no remote fetch.
import type{Stream}from'../../../src/lib/frdoFoundation/types.ts';
const owned={"dpo":"","po":""} as const;
export async function ownedFrdoDonor(stream:Stream){const raw=atob(owned[stream]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;}
